def solve():
    s = sys.stdin.read().strip()
    if not s:
        print(0)
        return
    n = len(s)
    def expand(l, r):
        while l >= 0 and r < n and s[l] == s[r]:
            l -= 1
            r += 1
        return r - l - 1
    max_len = 1
    for i in range(n):
        max_len = max(max_len, expand(i, i), expand(i, i + 1))
    print(max_len)
